$ss = fn(string $f) => asset('vendor/smartslider/' . $f);
$parSlide = function (string $modele) use ($nbSlides): string {
    $css = '';
    for ($n = 1; $n <= $nbSlides; $n++) {
        $css .= str_replace('{n}', (string) $n, $modele);
    }
    return $css;
};
